const AuthCtx=createContext<{user:User|null;setUser:(v:User|null)=>void}>({user:null,setUser:()=>{}});const useAuth=()=>useContext(AuthCtx);
const typeNames:Record<string,string>={TENDER_FEE:'Tender Fee',EMD_CHALLAN:'EMD by Challan',EMD_BG:'EMD by Bank Guarantee',FINANCIAL_DOCUMENTS:'Financial Documents',POWER_OF_ATTORNEY:'Power of Attorney',DECLARATION:'Declaration / Undertaking',HR_DOCUMENTS:'HR Documents',OMS_PACE_REDFLAG:'OMS / PACE / Red flag'};
